(()=>{
 const records=window.MindscapeResearch||[], input=document.querySelector('#resource-query'), grid=document.querySelector('#resource-grid');let topic='All',category='',limit=12;
 const tags=r=>[r.topic,...(/security|sandbox|safety|wasi|integrity/i.test(r.title+' '+r.description)?['Safety']:[]),...(/latency|performance|throughput|benchmark/i.test(r.title+' '+r.description)?['Performance']:[]),...(/architecture|state|trac/i.test(r.title)?['Architecture']:[])];
 const thumbnails=r=>{const text=(r.title+' '+r.description).toLowerCase();if(/latency|throughput/.test(text))return '07-dedicated-latency';if(/humaneval|historical.model/.test(text))return '06-humaneval-context';if(/zero.weight|singleton/.test(text))return '05-zero-weight-controls';if(r.topic==='Numeric')return '04-numeric-masking';if(/learning|training|budget/.test(text))return '02-coding-learning-ood_test';if(/foundation|smollm/.test(text))return '03-smollm2-ood_test';return '01-coding-lockbox'};
 function render(){const q=input.value.toLowerCase().trim();let result=records.filter(r=>(topic==='All'||tags(r).includes(topic))&&(!category||r.category===category)&&(r.title+' '+r.description+' '+r.topic+' '+r.category+' '+r.source).toLowerCase().includes(q));const sort=document.querySelector('#resource-sort').value;if(sort==='title')result.sort((a,b)=>a.title.localeCompare(b.title));if(sort==='pages')result.sort((a,b)=>b.pages-a.pages);grid.replaceChildren();for(const r of result.slice(0,limit)){const a=document.createElement('a');a.className='resource-card';a.href='../assets/reports/'+r.file;const art=document.createElement('div');art.className='resource-art';art.setAttribute('aria-hidden','true');const image=document.createElement('img');image.src='../assets/graphs/'+thumbnails(r)+'.png';image.alt='';image.loading='lazy';image.decoding='async';art.append(image);const content=document.createElement('div');content.className='resource-card-content';const h=document.createElement('h3');h.textContent=r.title+' ↗';const p=document.createElement('p');p.textContent=r.description;const meta=document.createElement('div');meta.className='resource-meta';const type=document.createElement('span');type.textContent=r.category+' · '+r.topic;const pages=document.createElement('span');pages.textContent='PDF · '+r.pages+' pages';meta.append(type,pages);content.append(h,p,meta);a.append(art,content);grid.append(a)}document.querySelector('#result-count').textContent=`${result.length} ${result.length===1?'resource':'resources'}${topic==='All'?'':' · '+topic}${category?' · '+category:''}`;document.querySelector('#resource-empty').hidden=!!result.length;document.querySelector('#resource-more').hidden=limit>=result.length;document.querySelector('#clear-search').hidden=!q;document.querySelector('#tracks').hidden=!!q||topic!=='All'||!!category;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===topic)));document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===category)))}
 document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{topic=b.dataset.filter===topic?'All':b.dataset.filter;category='';limit=12;render()}));document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category===category?'':b.dataset.category;topic='All';limit=12;render()}));input.addEventListener('input',()=>{limit=12;render()});document.querySelector('#resource-sort').addEventListener('change',render);document.querySelector('#resource-more').addEventListener('click',()=>{limit+=12;render()});document.querySelector('#clear-search').addEventListener('click',()=>{input.value='';render();input.focus()});document.querySelector('#reset-filters').addEventListener('click',()=>{input.value='';topic='All';category='';limit=12;render();input.focus()});render();
})();
